(function($, elementor) {
    $(window).on('elementor/frontend/init', function() {
        let moduleHandler = elementorModules.frontend.handlers.Base;
        let VLP_Split_Scroll_Alt;

        VLP_Split_Scroll_Alt = moduleHandler.extend({
            getDefaultSettings() {
                return {
                    selectors: {
                        main: '.vlp-split-scroll-alt-main'
                    }
                }
            },
            getDefaultElements() {
                const {
                    main
                } = this.getSettings('selectors');

                return {
                    $main: this.$element.find(main)
                }
            },
            bindEvents: function() {
                let $this = this;
                if (!$this._isMobile()) {
                    this._execute();
                }
            },
            _execute() {
                gsap.registerPlugin(ScrollTrigger);
                gsap.config({
                    nullTargetWarn: false,
                    trialWarn: false
                });

                let mm = gsap.matchMedia();
                let $id = this.getID();
                let $main = this.elements.$main;

                let $allImgSecs = $('.vlp-split-scroll-img-item', $main);
                let $allContentSecs = $('.vlp-split-scroll-content-item', $main);
                let $contentSecWrap = $('.vlp-split-scroll-right-items-wrap', $main);
                let $firstContentItem = $('.vlp-split-scroll-content-item:first-child', $main);
                let $lastContentItem = $('.vlp-split-scroll-content-item:last-child', $main);

                let $allContentSecsAlt = $('.vlp-split-scroll-content-wrap', $main);
                let gap = $allContentSecsAlt.length * 30;

                // this setup code only runs when viewport is at least 992px wide
                mm.add("(min-width: 992px)", function() {
                    gsap.timeline({
                        scrollTrigger: {
                            pin: true,
                            scrub: 1,
                            trigger: $contentSecWrap,
                            end: () => "+=" + (($main.height() + gap) - document.documentElement.clientHeight),
                            onUpdate: (self) => {
                                let $per = parseInt(self.progress * 100);
                                if ($per > 99) {
                                    $lastContentItem.addClass("last");
                                } else {
                                    $lastContentItem.removeClass("last");
                                }

                                if ($per < 1) {
                                    $firstContentItem.addClass("first");
                                } else {
                                    $firstContentItem.removeClass("first");
                                }
                            },
                        },
                        defaults: {
                            ease: "none",
                            duration: 1
                        }
                    });

                    $allImgSecs.each(function($index, $item) {
                        let $pos = $allContentSecs[$index];
                        ScrollTrigger.create({
                            trigger: $item,
                            start: "top center",
                            end: () => '+=' + $item.offsetHeight,
                            toggleClass: {
                                targets: [$pos],
                                className: "active"
                            },
                        });
                    });
                });
            },
            _isMobile() {
                let isAndroid = navigator.userAgent.match(/Android/i),
                    isBlackBerry = navigator.userAgent.match(/BlackBerry/i),
                    isIOS = navigator.userAgent.match(/iPhone|iPad|iPod/i),
                    isOpera = navigator.userAgent.match(/Opera Mini/i),
                    isWindows = navigator.userAgent.match(/IEMobile|Windows Phone/i);

                return (
                    isAndroid ||
                    isBlackBerry ||
                    isIOS ||
                    isOpera ||
                    isWindows
                );
            },
        });

        elementorFrontend.elementsHandler.attachHandler('vlp-split-scroll-alt', VLP_Split_Scroll_Alt);
    });
})(jQuery, window.elementorFrontend);